import type { BankQuestion } from "@/lib/bank";

/** Practical and Analytical Chemistry (Chemistry (JEE/NEET)): 100 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"chem-practical-salt-analysis-1","question":"The brown ring test is used to detect the:","options":["Carbonate ion","Nitrate ion","Sulphate ion","Chloride ion"],"answer":1,"explanation":"A brown ring of [Fe(H₂O)₅(NO)]²⁺ forms at the junction when conc. H₂SO₄ is layered under a nitrate solution mixed with FeSO₄.","difficulty":"easy","source":"NEET"},
  {"id":"chem-practical-salt-analysis-2","question":"Nessler's reagent (alkaline K₂HgI₄) gives a brown precipitate with:","options":["Iodide ion","Ammonium ion","Sodium ion","Nitrate ion"],"answer":1,"explanation":"NH₄⁺ (as NH₃) gives the brown iodide of Millon's base with Nessler's reagent.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-practical-salt-analysis-3","question":"In Lassaigne's test, the presence of nitrogen in an organic compound is shown by the formation of:","options":["Prussian blue","A blood-red colour","A violet colour","A black precipitate"],"answer":0,"explanation":"Fusion with Na converts N (with C) into NaCN; with FeSO₄, then FeCl₃/acid, it gives Fe₄[Fe(CN)₆]₃, Prussian blue. Blood red appears when both N and S are present.","difficulty":"easy","source":"NEET"},
  {"id":"chem-practical-salt-analysis-4","question":"In qualitative analysis, the group reagent for group II cations is:","options":["H₂S gas in the presence of dilute HCl","NH₄OH in the presence of NH₄Cl","Dilute HCl","(NH₄)₂CO₃ in the presence of NH₄OH"],"answer":0,"explanation":"Group II (Cu²⁺, Pb²⁺, Cd²⁺, As³⁺ etc.) sulphides precipitate in acidic H₂S. Dilute HCl is group I; NH₄OH/NH₄Cl is group III; (NH₄)₂CO₃ is group V.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-practical-salt-analysis-5","question":"The chromyl chloride test is used to confirm the presence of:","options":["Chromate ion","Iodide ion","Chloride ion","Bromide ion"],"answer":2,"explanation":"A chloride heated with K₂Cr₂O₇ and conc. H₂SO₄ gives orange-red CrO₂Cl₂ vapours; passed into NaOH they give yellow Na₂CrO₄, which precipitates yellow PbCrO₄ with lead acetate. Bromides and iodides give no chromyl compound.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-practical-salt-analysis-6","question":"A cation gives a chocolate-brown precipitate with potassium ferrocyanide, K₄[Fe(CN)₆]. The cation is:","options":["Pb²⁺","Fe³⁺","Cu²⁺","Zn²⁺"],"answer":2,"explanation":"Cu₂[Fe(CN)₆] is chocolate brown. Fe³⁺ gives Prussian blue and Zn²⁺ a white/bluish-white precipitate.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-practical-salt-analysis-7","question":"Steam distillation is used to purify compounds that are:","options":["Liquids that decompose below 100 °C in steam","Volatile in steam and immiscible with water","Sublimable solids","Soluble in water and non-volatile"],"answer":1,"explanation":"The mixture boils when the sum of the two vapour pressures reaches atmospheric pressure, below 100 °C, so compounds such as aniline distil without decomposing.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-practical-salt-analysis-8","question":"The most suitable indicator for titrating a weak base (aqueous NH₃) with a strong acid (HCl) is:","options":["Methyl orange","Starch","Litmus","Phenolphthalein"],"answer":0,"explanation":"The end point lies in the acidic range (pH ≈ 5), matching methyl orange (3.1–4.4). Phenolphthalein changes at pH 8–10, where the weak base is far from neutralised.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-practical-salt-analysis-9","question":"Fe³⁺ ions give a blood-red colour with:","options":["Potassium thiocyanate","Dimethylglyoxime","Sodium hydroxide","Potassium ferricyanide"],"answer":0,"explanation":"Fe³⁺ + SCN⁻ → [Fe(SCN)]²⁺ (blood red). NaOH gives a reddish-brown precipitate; dimethylglyoxime is the test for Ni²⁺.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-practical-salt-analysis-10","question":"In group III analysis, NH₄Cl is added before NH₄OH because:","options":["NH₄Cl oxidises Fe²⁺ to Fe³⁺","The common ion NH₄⁺ suppresses the ionisation of NH₄OH, keeping [OH⁻] too low to precipitate hydroxides of groups IV and V","NH₄Cl itself precipitates Al³⁺","It increases [OH⁻] so that all hydroxides precipitate"],"answer":1,"explanation":"Only the hydroxides with very low Ksp (Fe³⁺, Al³⁺, Cr³⁺) exceed their solubility product; Zn²⁺, Mn²⁺, Mg²⁺ stay in solution. Oxidation of Fe²⁺ is done separately with conc. HNO₃.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-practical-salt-analysis-11","question":"In Lassaigne's test, if both nitrogen and sulphur are present, a blood-red colour is obtained with FeCl₃ because of:","options":["Formation of Prussian blue","Formation of sodium nitroprusside","Formation of Fe(SCN)²⁺ from NaSCN in the extract","Formation of Na₂S"],"answer":2,"explanation":"With enough of both elements, fusion gives NaSCN, which gives blood-red [Fe(SCN)]²⁺ with Fe³⁺. Excess sodium can decompose NaSCN into NaCN + Na₂S.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-practical-salt-analysis-12","question":"In the Dumas method, 0.30 g of an organic compound gives 50 mL of N₂ measured at STP. The percentage of nitrogen in the compound is:","options":["20.8%","10.4%","41.7%","16.7%"],"answer":0,"explanation":"Mass of N₂ = 28 × 50/22400 = 0.0625 g; %N = 0.0625/0.30 × 100 = 20.8%.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-practical-salt-analysis-13","question":"In a Kjeldahl estimation, the ammonia from 0.50 g of an organic compound is neutralised by 10 mL of 0.5 M H₂SO₄. The percentage of nitrogen is:","options":["14%","56%","28%","7%"],"answer":2,"explanation":"Moles H₂SO₄ = 0.005, which neutralise 0.010 mol NH₃ = 0.010 mol N = 0.14 g. %N = 0.14/0.50 × 100 = 28%. Forgetting the 2 : 1 ratio gives 14%.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-practical-salt-analysis-14","question":"In the Carius method, 0.25 g of an organic compound gives 0.47 g of AgBr (molar mass 188). The percentage of bromine is:","options":["60%","80%","20%","40%"],"answer":1,"explanation":"Mass of Br = 0.47 × 80/188 = 0.20 g; %Br = 0.20/0.25 × 100 = 80%.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-practical-salt-analysis-15","question":"In paper chromatography a substance moves 3.0 cm while the solvent front moves 12.0 cm from the starting line. The Rf value is:","options":["0.75","4.0","0.33","0.25"],"answer":3,"explanation":"Rf = distance moved by the substance/distance moved by the solvent = 3.0/12.0 = 0.25. Rf is always less than 1.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-practical-salt-analysis-16","question":"A salt gives an apple-green colour to the flame. The cation present is most likely:","options":["K⁺","Ca²⁺","Sr²⁺","Ba²⁺"],"answer":3,"explanation":"Barium gives apple green, calcium brick red, strontium crimson and potassium lilac.","difficulty":"hard","source":"NEET"},
  {"id":"chem-practical-salt-analysis-17","question":"Which cation is precipitated as a white sulphide when H₂S is passed through its ammoniacal solution (group IV)?","options":["Co²⁺","Ni²⁺","Zn²⁺","Mn²⁺"],"answer":2,"explanation":"ZnS is white; MnS is buff (flesh) coloured; NiS and CoS are black.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-practical-salt-analysis-18","question":"A solution gives a white precipitate with BaCl₂ that does not dissolve in dilute HCl. The anion present is:","options":["Sulphate","Chloride","Sulphite","Carbonate"],"answer":0,"explanation":"BaSO₄ is insoluble in acids. BaSO₃ and BaCO₃ dissolve in dilute HCl with evolution of SO₂ and CO₂; chloride gives no precipitate with BaCl₂.","difficulty":"hard","source":"NEET"},
  {"id":"chem-practical-salt-analysis-19","question":"How many of the following statements are correct? (A) Lassaigne's extract is prepared by fusing the organic compound with sodium metal. (B) The Kjeldahl method is suitable for estimating nitrogen in nitrobenzene. (C) In the Carius method sulphur is estimated as BaSO₄. (D) A green flame in the Beilstein test confirms the presence of a halogen beyond doubt.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"A and C are correct. B is wrong: nitro, azo compounds and ring nitrogen (pyridine) do not convert to (NH₄)₂SO₄. D is wrong: urea, thiourea and some other compounds also give a green flame, so the Beilstein test is not conclusive.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-practical-salt-analysis-20","question":"A salt solution gives a white precipitate with dilute HCl. The precipitate dissolves in hot water, and this hot solution gives a yellow precipitate with K₂CrO₄. The cation is:","options":["Ba²⁺","Hg₂²⁺","Ag⁺","Pb²⁺"],"answer":3,"explanation":"PbCl₂ is soluble in hot water; Pb²⁺ then gives yellow PbCrO₄. AgCl does not dissolve in hot water, Hg₂Cl₂ turns black with NH₃, and BaCl₂ is soluble so Ba²⁺ gives no group I precipitate.","difficulty":"very-hard","source":"NEET"},
  {"id":"chem-practical-salt-analysis-21","question":"Assertion (A): Dilute HCl is added to the solution before passing H₂S for the precipitation of group II cations. Reason (R): The H⁺ from HCl suppresses the ionisation of H₂S, so [S²⁻] is kept low and only sulphides with very low Ksp precipitate.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both true and R explains A: by the common-ion effect only group II sulphides (very low Ksp) exceed their solubility product, while group IV sulphides (ZnS, MnS, NiS, CoS) do not.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-practical-salt-analysis-22","question":"Match the ion (Column I) with its test (Column II). (a) NH₄⁺, (b) PO₄³⁻, (c) Fe³⁺, (d) Ni²⁺. (1) Yellow precipitate with ammonium molybdate on warming with HNO₃; (2) Rosy-red precipitate with dimethylglyoxime in ammoniacal medium; (3) Brown precipitate with alkaline K₂HgI₄; (4) Blood-red colour with KSCN.","options":["a-3, b-4, c-1, d-2","a-3, b-1, c-4, d-2","a-1, b-3, c-4, d-2","a-3, b-1, c-2, d-4"],"answer":1,"explanation":"NH₄⁺: Nessler's reagent; PO₄³⁻: ammonium phosphomolybdate; Fe³⁺: [Fe(SCN)]²⁺; Ni²⁺: nickel dimethylglyoximate.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-practical-salt-analysis-23","question":"A sodium salt gives a yellow precipitate with AgNO₃ that is insoluble even in concentrated ammonia. With chlorine water and CCl₄, the organic layer turns violet. The anion is:","options":["Iodide","Bromide","Chloride","Sulphide"],"answer":0,"explanation":"AgI is yellow and insoluble in NH₃ (AgBr is pale yellow and dissolves slightly in conc. NH₃; AgCl dissolves readily). Cl₂ liberates I₂, violet in CCl₄; Br₂ would be orange-brown.","difficulty":"very-hard","source":"NEET"},
  {"id":"chem-practical-salt-analysis-24","question":"In a Carius estimation, 0.32 g of an organic compound gives 0.466 g of BaSO₄ (molar mass 233). The percentage of sulphur is:","options":["20%","10%","40%","14.6%"],"answer":0,"explanation":"Mass of S = 0.466 × 32/233 = 0.064 g; %S = 0.064/0.32 × 100 = 20%.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-practical-salt-analysis-25","question":"Which of the following will NOT give a Prussian blue colour in Lassaigne's test for nitrogen?","options":["Urea","Glycine","Aniline","Hydrazine (NH₂NH₂)"],"answer":3,"explanation":"The test needs NaCN, which forms only if both carbon and nitrogen are present. Hydrazine contains no carbon.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-practical-salt-analysis-26","question":"A compound gives effervescence with aqueous NaHCO₃ and a violet colour with neutral FeCl₃ solution. The compound is:","options":["Salicylic acid","Benzyl alcohol","Benzoic acid","Phenol"],"answer":0,"explanation":"–COOH releases CO₂ from NaHCO₃ and the phenolic –OH gives the violet FeCl₃ colour. Phenol fails the NaHCO₃ test; benzoic acid gives a buff precipitate with FeCl₃, not violet.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-practical-salt-analysis-27","question":"How many of the following statements about purification are correct? (A) Fractional distillation separates liquids whose boiling points are close to each other. (B) Glycerol is purified by distillation under reduced pressure because it decomposes at its normal boiling point. (C) Camphor and naphthalene can be purified by sublimation. (D) Differential extraction works because the compound is more soluble in the organic solvent than in water.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: each describes the standard basis of the technique (repeated vaporisation–condensation, lowering the boiling point, direct solid-to-vapour change, and partitioning between immiscible solvents).","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-practical-salt-analysis-28","question":"A solution contains Ba²⁺, Al³⁺, Cu²⁺ and Mn²⁺. In systematic group analysis, the order in which they are precipitated is:","options":["Cu²⁺, Mn²⁺, Al³⁺, Ba²⁺","Cu²⁺, Al³⁺, Mn²⁺, Ba²⁺","Al³⁺, Cu²⁺, Ba²⁺, Mn²⁺","Ba²⁺, Cu²⁺, Al³⁺, Mn²⁺"],"answer":1,"explanation":"Cu²⁺ is group II (acidic H₂S), Al³⁺ group III (NH₄OH/NH₄Cl), Mn²⁺ group IV (H₂S in ammoniacal medium) and Ba²⁺ group V ((NH₄)₂CO₃).","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-practical-salt-analysis-29","question":"0.63 g of oxalic acid dihydrate (H₂C₂O₄·2H₂O, molar mass 126) is dissolved to make 100 mL of solution. The volume of 0.1 M NaOH needed to neutralise 20 mL of this solution is:","options":["20 mL","40 mL","5 mL","10 mL"],"answer":0,"explanation":"Molarity = (0.63/126)/0.1 L = 0.05 M; 20 mL contains 1 × 10⁻³ mol of the dibasic acid, needing 2 × 10⁻³ mol NaOH = 20 mL of 0.1 M. 10 mL treats oxalic acid as monobasic.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-practical-salt-analysis-30","question":"Which statement about the brown ring test is INCORRECT?","options":["It is carried out by adding dilute HCl to a mixture of the salt solution and FeSO₄","The brown ring is due to [Fe(H₂O)₅(NO)]²⁺","Nitrite ions interfere and must be removed before testing for nitrate","Concentrated H₂SO₄ is poured slowly along the side of the test tube"],"answer":0,"explanation":"Concentrated H₂SO₄ is needed to reduce NO₃⁻ to NO and it forms the lower layer where the ring appears. Nitrite gives the ring even with dilute acid, so it interferes and is destroyed first (e.g. with urea or sulphamic acid).","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-31", "question": "Potassium salts impart which colour to a non-luminous flame?", "options": ["Crimson red", "Lilac (violet)", "Golden yellow", "Brick red"], "answer": 1, "explanation": "Potassium gives a lilac flame (seen through blue cobalt glass to cut out sodium's yellow). Golden yellow is Na, brick red Ca and crimson Sr or Li.", "difficulty": "easy", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-32", "question": "The group reagent for group V cations (Ba²⁺, Sr²⁺, Ca²⁺) is:", "options": ["(NH₄)₂CO₃ in the presence of NH₄Cl and NH₄OH", "Dilute HCl", "NH₄OH in the presence of NH₄Cl", "H₂S in the presence of dilute HCl"], "answer": 0, "explanation": "Group V cations are precipitated as carbonates by ammonium carbonate in ammoniacal solution containing NH₄Cl. NH₄Cl keeps Mg²⁺ (group VI) in solution.", "difficulty": "easy", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-33", "question": "In redox titrations with potassium permanganate, the indicator used is:", "options": ["Methyl orange", "Starch", "KMnO₄ itself (self-indicator)", "Phenolphthalein"], "answer": 2, "explanation": "MnO₄⁻ is intensely purple while Mn²⁺ is almost colourless, so the first drop of excess KMnO₄ gives a permanent pink colour at the end point.", "difficulty": "easy", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-34", "question": "A salt gives a blue borax bead in both the oxidising and the reducing flame. The cation present is:", "options": ["Co²⁺", "Fe³⁺", "Ni²⁺", "Cu²⁺"], "answer": 0, "explanation": "Cobalt gives a blue (cobalt metaborate) bead in both flames. Copper gives a blue bead in the oxidising flame but a red, opaque bead in the reducing flame.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-35", "question": "A colourless gas turns lime water milky and also turns acidified K₂Cr₂O₇ paper green. The gas is:", "options": ["NO₂", "SO₂", "CO₂", "H₂S"], "answer": 1, "explanation": "Both CO₂ and SO₂ turn lime water milky, but only SO₂, a reducing gas, reduces Cr₂O₇²⁻ (orange) to Cr³⁺ (green). This tells sulphite from carbonate.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-36", "question": "In group VI analysis, Mg²⁺ is confirmed by a white crystalline precipitate formed with:", "options": ["Potassium chromate", "Ammonium oxalate", "Dimethylglyoxime", "Disodium hydrogen phosphate in the presence of NH₄OH"], "answer": 3, "explanation": "Mg²⁺ + HPO₄²⁻ + NH₄OH → Mg(NH₄)PO₄ (white). Ammonium oxalate is used for Ca²⁺, K₂CrO₄ for Ba²⁺ and dimethylglyoxime for Ni²⁺.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-37", "question": "Before testing Lassaigne's extract for halogens with AgNO₃, it is boiled with dilute HNO₃ in order to:", "options": ["Precipitate the sodium ions", "Decompose any NaCN and Na₂S present", "Convert halides into free halogens", "Oxidise Fe²⁺ to Fe³⁺"], "answer": 1, "explanation": "If N or S is present, CN⁻ and S²⁻ would also give precipitates with Ag⁺ (AgCN, Ag₂S). Boiling with HNO₃ drives them off as HCN and H₂S.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-38", "question": "Camphor, naphthalene and benzoic acid are usually purified by:", "options": ["Fractional crystallisation", "Distillation under reduced pressure", "Steam distillation", "Sublimation"], "answer": 3, "explanation": "These solids pass directly into vapour on heating and condense back as pure solid, leaving non-volatile impurities behind.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-39", "question": "Dilute HCl is not used to acidify the solution in a KMnO₄ titration because:", "options": ["Cl⁻ is oxidised to Cl₂ by KMnO₄, so extra permanganate is used", "HCl forms a precipitate with Mn²⁺", "HCl decolourises Fe³⁺", "HCl is a weak acid"], "answer": 0, "explanation": "MnO₄⁻ oxidises chloride to chlorine, so the titre comes out too high. Dilute H₂SO₄, whose sulphate is not oxidised, is used instead.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-40", "question": "Which anion gives brown fumes even with dilute H₂SO₄?", "options": ["NO₂⁻", "Br⁻", "NO₃⁻", "CH₃COO⁻"], "answer": 0, "explanation": "Nitrous acid is unstable: 2NO₂⁻ + 2H⁺ → NO + NO₂ + H₂O, giving brown fumes in the cold with dilute acid. Nitrate (and bromide) gives brown fumes only with concentrated H₂SO₄.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-41", "question": "A salt gives a vinegar-like smell with dilute H₂SO₄, and its neutral solution gives a deep red colour with neutral FeCl₃. The anion is:", "options": ["Carbonate", "Formate", "Oxalate", "Acetate"], "answer": 3, "explanation": "Acetate releases acetic acid (vinegar smell) with dilute acid and forms deep red iron(III) acetate with neutral FeCl₃, which gives a brown-red precipitate on boiling.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-42", "question": "In group III, Al³⁺ is confirmed by the 'lake test', in which:", "options": ["A blood-red colour forms with NH₄SCN", "A yellow precipitate forms with ammonium molybdate", "A blue bead forms with borax", "Al(OH)₃ adsorbs blue litmus and floats as a blue lake in a colourless solution"], "answer": 3, "explanation": "The white gelatinous Al(OH)₃ (from dissolving in NaOH and re-precipitating) adsorbs the blue colour of litmus, so a blue mass floats in a colourless liquid.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-43", "question": "A group IV cation gives a blue colour in the amyl alcohol layer when NH₄SCN is added to its solution. The cation is:", "options": ["Zn²⁺", "Co²⁺", "Mn²⁺", "Ni²⁺"], "answer": 1, "explanation": "Co²⁺ forms the blue complex [Co(SCN)₄]²⁻, which dissolves in amyl alcohol. Ni²⁺ is confirmed with dimethylglyoxime (rosy red).", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-44", "question": "In the estimation of phosphorus, 0.20 g of an organic compound gives 0.222 g of Mg₂P₂O₇ (molar mass 222). The percentage of phosphorus is:", "options": ["22.2%", "15.5%", "31.0%", "62.0%"], "answer": 2, "explanation": "1 mol Mg₂P₂O₇ contains 2 × 31 = 62 g P. Mass of P = 0.222 × 62/222 = 0.062 g, so %P = 0.062/0.20 × 100 = 31.0%. 15.5% counts only one P atom per formula.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-45", "question": "In adsorption column chromatography on alumina, the component of a mixture that comes out of the column first is the one that is:", "options": ["Highest in molar mass", "Least strongly adsorbed", "Most strongly adsorbed", "Present in the largest amount"], "answer": 1, "explanation": "The weakly adsorbed component spends more time in the moving solvent and is eluted first; the strongly adsorbed one is held near the top and comes out later.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-46", "question": "Before group III, the filtrate from group II is boiled with a few drops of conc. HNO₃ in order to:", "options": ["Oxidise Fe²⁺ to Fe³⁺, since Fe(OH)₂ is not completely precipitated by NH₄OH/NH₄Cl", "Precipitate Al³⁺ as Al(OH)₃", "Destroy NH₄Cl", "Remove sulphate ions"], "answer": 0, "explanation": "Fe(OH)₂ has a much higher solubility product, so it would be incompletely precipitated in the buffered NH₄Cl/NH₄OH medium. Fe³⁺ precipitates completely as reddish-brown Fe(OH)₃. (The H₂S is also boiled off.)", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-47", "question": "Lead can appear in both group I and group II of salt analysis because:", "options": ["Pb²⁺ is oxidised to Pb⁴⁺ by HCl", "Pb²⁺ forms a complex with H₂S", "PbS is soluble in dilute HCl", "PbCl₂ is appreciably soluble in cold water, so not all Pb²⁺ is precipitated in group I"], "answer": 3, "explanation": "PbCl₂ is fairly soluble (more so in hot water), so some Pb²⁺ remains in the filtrate and is then precipitated as black PbS by H₂S in group II.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-48", "question": "For the analysis of anions, a sodium carbonate extract of the salt is prepared because:", "options": ["Na₂CO₃ oxidises all the anions", "Anions pass into solution as sodium salts while interfering cations are precipitated as carbonates", "It decomposes all the anions into gases", "It removes all the halides"], "answer": 1, "explanation": "Boiling with Na₂CO₃ converts the anions into soluble sodium salts and precipitates most heavy-metal cations as insoluble carbonates, so they cannot interfere with the anion tests.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-49", "question": "0.23 g of an organic compound containing C, H and O gives 0.44 g of CO₂ and 0.27 g of H₂O on complete combustion. Its empirical formula is:", "options": ["C₂H₆O", "CH₂O", "CH₃O", "C₂H₄O"], "answer": 0, "explanation": "C = 0.44 × 12/44 = 0.12 g (0.01 mol); H = 0.27 × 2/18 = 0.03 g (0.03 mol); O = 0.23 − 0.15 = 0.08 g (0.005 mol). C : H : O = 2 : 6 : 1, so C₂H₆O.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-50", "question": "How many of the following statements about anion tests are correct? (A) Sulphide ions give a violet (purple) colour with sodium nitroprusside. (B) Sulphite ions decolourise acidified KMnO₄. (C) Bromide heated with MnO₂ and conc. H₂SO₄ gives brown vapours. (D) Iodide also gives the chromyl chloride test, forming CrO₂I₂.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, B and C are correct. D is wrong: bromides and iodides do not form chromyl compounds; the chromyl chloride test is specific for chloride.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-51", "question": "Assertion (A): Diazonium salts often do not give a positive Lassaigne's test for nitrogen. Reason (R): Diazonium salts lose nitrogen as N₂ on heating before they can react with the fused sodium.", "options": ["Both A and R are true, and R explains A", "Both A and R are true, but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A: the nitrogen escapes as N₂ gas, so no NaCN forms and no Prussian blue appears.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "chem-practical-salt-analysis-52", "question": "Match the cation (Column I) with the colour of its sulphide precipitate (Column II). (a) Cu²⁺, (b) Cd²⁺, (c) Sb³⁺, (d) Mn²⁺. (1) Orange, (2) Buff (flesh-coloured), (3) Black, (4) Yellow.", "options": ["a-3, b-4, c-1, d-2", "a-3, b-1, c-4, d-2", "a-3, b-4, c-2, d-1", "a-4, b-3, c-1, d-2"], "answer": 0, "explanation": "CuS is black and CdS yellow (group II); Sb₂S₃ is orange (group II); MnS is buff or flesh-coloured (group IV).", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-53", "question": "A colourless salt dissolves in water. Its solution gives no precipitate with dilute HCl, with H₂S in acid, or with NH₄Cl + NH₄OH, but gives a white precipitate when H₂S is then passed through the ammoniacal solution. With conc. H₂SO₄ the solid salt gives a colourless gas that forms dense white fumes with ammonia. The salt is:", "options": ["AlCl₃", "CaCl₂", "ZnCl₂", "ZnSO₄"], "answer": 2, "explanation": "A white sulphide in group IV means Zn²⁺. HCl gas (white NH₄Cl fumes with NH₃) means chloride. Al³⁺ would already have been precipitated by NH₄OH in group III, and Ca²⁺ gives no sulphide.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-54", "question": "3.92 g of Mohr's salt (FeSO₄·(NH₄)₂SO₄·6H₂O, molar mass 392) is dissolved to make 100 mL. The volume of 0.02 M KMnO₄ needed to titrate 20 mL of this solution in acid is:", "options": ["4 mL", "20 mL", "100 mL", "40 mL"], "answer": 1, "explanation": "Fe²⁺ concentration = 0.01 mol/0.1 L = 0.1 M, so 20 mL has 0.002 mol Fe²⁺. MnO₄⁻ + 5Fe²⁺ + 8H⁺ → Mn²⁺ + 5Fe³⁺ + 4H₂O needs 0.0004 mol MnO₄⁻ = 20 mL of 0.02 M. 100 mL ignores the 1 : 5 ratio.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "chem-practical-salt-analysis-55", "question": "In a Dumas estimation, 0.25 g of an organic compound gives 40 mL of moist N₂ collected at 300 K and 725 mm Hg (aqueous tension 25 mm Hg). The percentage of nitrogen is about:", "options": ["20.0%", "17.4%", "16.8%", "14.0%"], "answer": 2, "explanation": "Dry-gas pressure = 700 mm Hg. Volume at STP = 40 × (700/760) × (273/300) = 33.5 mL; mass of N₂ = 33.5 × 28/22400 = 0.0419 g; %N = 0.0419/0.25 × 100 ≈ 16.8%. Ignoring the aqueous tension gives 17.4%.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "chem-practical-salt-analysis-56", "question": "How many of the following statements about cation tests are correct? (A) Cu²⁺ gives a deep blue solution with excess aqueous NH₃. (B) Fe³⁺ gives Prussian blue with potassium ferrocyanide. (C) Zn²⁺ gives a white (bluish-white) precipitate with potassium ferrocyanide. (D) Ca²⁺ gives a brick-red flame while Sr²⁺ gives a crimson flame.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct: [Cu(NH₃)₄]²⁺ is deep blue; Fe₄[Fe(CN)₆]₃ is Prussian blue; Zn₂[Fe(CN)₆] is white; Ca and Sr flames are brick red and crimson.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-57", "question": "Which statement about Beilstein's test for halogens is correct?", "options": ["Fluorine-containing compounds give the most intense green flame", "It requires fusion of the compound with sodium metal", "It distinguishes chlorine, bromine and iodine from one another", "Some halogen-free compounds, such as urea and thiourea, also give a green flame, so the test is not conclusive"], "answer": 3, "explanation": "A copper wire coated with the compound gives a green flame from volatile copper halides. It cannot tell one halogen from another, fluorides do not respond (CuF₂ is not volatile), and urea and thiourea give a green flame because they form volatile copper cyanide.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-58", "question": "In a Kjeldahl estimation, the ammonia from 0.50 g of an organic compound is passed into 50 mL of 0.5 M H₂SO₄. The excess acid needs 70 mL of 0.5 M NaOH for neutralisation. The percentage of nitrogen in the compound is:", "options": ["42%", "28%", "56%", "21%"], "answer": 0, "explanation": "H⁺ taken = 50 × 0.5 × 2 = 50 mmol; NaOH = 35 mmol. NH₃ = 50 − 35 = 15 mmol, i.e. 0.21 g N. %N = 0.21/0.50 × 100 = 42%. Treating H₂SO₄ as monobasic would give an impossible result.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "chem-practical-salt-analysis-59", "question": "A green crystalline salt dissolves in water. Its solution gives a dark blue precipitate with potassium ferricyanide, K₃[Fe(CN)₆], and a white precipitate with BaCl₂ that does not dissolve in dilute HCl. The salt is:", "options": ["NiSO₄", "CuSO₄", "FeCl₃", "FeSO₄"], "answer": 3, "explanation": "Fe²⁺ forms Turnbull's blue with ferricyanide, and BaSO₄ that does not dissolve in HCl shows sulphate: FeSO₄·7H₂O is green. NiSO₄ is green but gives no blue precipitate; FeCl₃ is yellow-brown and contains no sulphate.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-practical-salt-analysis-60", "question": "25 mL of a solution containing NaOH and Na₂CO₃ needs 15 mL of 0.1 M HCl to reach the phenolphthalein end point, and then a further 5 mL to reach the methyl orange end point. The mole ratio NaOH : Na₂CO₃ in the solution is:", "options": ["3 : 1", "2 : 1", "1 : 1", "1 : 2"], "answer": 1, "explanation": "The extra 5 mL (HCO₃⁻ → H₂CO₃) equals the carbonate: 0.5 mmol Na₂CO₃. The first 15 mL (1.5 mmol) neutralises NaOH and turns CO₃²⁻ into HCO₃⁻, so NaOH = 1.5 − 0.5 = 1.0 mmol. Ratio 2 : 1.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"chem-practical-salt-analysis-61","question":"While preparing Mohr's salt, a few mL of dilute H₂SO₄ are added to the solution of FeSO₄·7H₂O and (NH₄)₂SO₄ in water. The main purpose of the acid is to:","options":["Suppress hydrolysis of Fe²⁺ (and slow its aerial oxidation), so the solution does not turn turbid and yellow","Supply extra sulphate ions so that the double salt precipitates","Oxidise Fe²⁺ to Fe³⁺ so that pale green crystals form","Lower the boiling point so the solution can be concentrated faster"],"answer":0,"explanation":"Fe²⁺ hydrolyses to basic iron salts and is easily air-oxidised to yellow-brown Fe³⁺; H⁺ from dilute H₂SO₄ pushes the hydrolysis back and keeps the solution clear. The acid is not there to oxidise iron (that would spoil the pale green crystals) or to provide sulphate.","difficulty":"moderate","source":"JEE Main"},
  {"id":"chem-practical-salt-analysis-62","question":"A positively charged ferric hydroxide sol is best prepared by:","options":["Adding NaOH solution in excess to cold FeCl₃ solution","Adding FeCl₃ solution drop by drop to a large volume of boiling water","Grinding Fe₂O₃ with water in a colloid mill without any electrolyte","Passing H₂S through a solution of FeCl₃"],"answer":1,"explanation":"FeCl₃ hydrolyses in boiling water to Fe(OH)₃ particles that adsorb Fe³⁺ (the common ion), giving a positive sol. Excess NaOH gives a gelatinous precipitate, not a sol, and H₂S reduces Fe³⁺ (giving sulphur), so neither gives the sol.","difficulty":"moderate","source":"JEE Main"},
  {"id": "chem-practical-salt-analysis-63", "question": "Which indicator is UNSUITABLE for titrating acetic acid with sodium hydroxide?", "options": ["Phenolphthalein (8.2–10)", "Thymol blue, alkaline range (8.0–9.6)", "Methyl orange (3.1–4.4)", "Thymolphthalein (9.3–10.5)"], "answer": 2, "explanation": "The equivalence point of a weak acid–strong base titration is alkaline (pH ≈ 8.5–9) because acetate hydrolyses, and the steep part of the curve lies above pH 7. Methyl orange changes colour at pH 3.1–4.4, long before the equivalence point, so it gives a falsely low titre.", "difficulty": "moderate", "source": "JEE Main"},
  {"id":"chem-practical-salt-analysis-64","question":"In the laboratory preparation of iodoform from acetone, the reagents used and the appearance of the product are:","options":["Acetone and KI in neutral solution; white powder with no smell","Acetone and HI; colourless needles with a sweet smell","Acetone, iodine and conc. H₂SO₄; violet crystals","Acetone, iodine and aqueous NaOH (or KI with NaOCl); yellow crystals with a characteristic antiseptic smell"],"answer":3,"explanation":"In base, the CH₃CO– group is iodinated three times and the CI₃ group is then cleaved off as CHI₃, a yellow solid (m.p. ≈ 392 K) with a 'hospital' smell. Acid does not cleave the triiodo ketone, and iodine alone in neutral KI does not halogenate fast.","difficulty":"moderate","source":"JEE Main"},
  {"id":"chem-practical-salt-analysis-65","question":"100 mL of 0.5 M HCl at 25.0 °C is mixed with 100 mL of 0.5 M NaOH at 25.0 °C in a calorimeter of heat capacity 40 J K⁻¹. The temperature rises to 28.2 °C. Taking the density of the solution as 1 g mL⁻¹ and its specific heat as 4.2 J g⁻¹ K⁻¹, the enthalpy of neutralisation is about:","options":["−56.3 kJ mol⁻¹","−53.8 kJ mol⁻¹","−28.2 kJ mol⁻¹","−112.6 kJ mol⁻¹"],"answer":0,"explanation":"q = (200 × 4.2 + 40) × 3.2 = 2688 + 128 = 2816 J for 0.05 mol of water formed, so ΔH = −2816/0.05 = −56.3 kJ mol⁻¹. Forgetting the calorimeter gives −53.8; using only 100 g of solution halves the heat.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-practical-salt-analysis-66","question":"1.60 g of anhydrous CuSO₄ (molar mass 160 g mol⁻¹) is dissolved in 100 g of water and the temperature rises by 1.6 K. Taking the heat capacity as that of 100 g of water (4.2 J g⁻¹ K⁻¹) and neglecting the calorimeter, the enthalpy of solution of anhydrous CuSO₄ is:","options":["+67.2 kJ mol⁻¹","−67.2 kJ mol⁻¹","−6.72 kJ mol⁻¹","−0.672 kJ mol⁻¹"],"answer":1,"explanation":"q = 100 × 4.2 × 1.6 = 672 J released by 0.01 mol, so ΔH = −672/0.01 = −67.2 kJ mol⁻¹. The temperature rose, so the process is exothermic and the sign is negative; dividing by 0.1 mol instead of 0.01 mol gives −6.72.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-practical-salt-analysis-67","question":"In the iodide–hydrogen peroxide 'clock' experiment, a fixed small amount of Na₂S₂O₃ and starch is added to the reaction mixture. Which statement explains why 1/t (t = time for the blue colour to appear) can be used as a measure of the initial rate?","options":["Thiosulphate catalyses the reaction, so its colour change marks completion","The blue colour appears only after all the H₂O₂ has been used up","The thiosulphate instantly converts the I₂ formed back to I⁻; blue appears when it is used up, i.e. when a fixed, small amount of I₂ has been produced","Starch reacts directly with H₂O₂, and the time is set by that reaction"],"answer":2,"explanation":"I₂ + 2S₂O₃²⁻ → 2I⁻ + S₄O₆²⁻ is very fast, so starch turns blue only after all thiosulphate is consumed, which corresponds to a fixed small extent of reaction; rate ≈ (fixed Δ[I₂])/t ∝ 1/t. The H₂O₂ is far from used up when the colour appears, so the method measures an initial rate.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-practical-salt-analysis-68","question":"20.0 mL of an oxalic acid solution needs 16.0 mL of 0.02 M KMnO₄ in hot dilute H₂SO₄. The concentration of the solution in grams of crystalline oxalic acid (H₂C₂O₄·2H₂O, molar mass 126) per litre is:","options":["3.60 g L⁻¹","12.6 g L⁻¹","2.02 g L⁻¹","5.04 g L⁻¹"],"answer":3,"explanation":"2MnO₄⁻ react with 5C₂O₄²⁻, so mol oxalic acid = (5/2) × 16.0 × 0.02 = 0.80 mmol in 20.0 mL, i.e. 0.040 M; 0.040 × 126 = 5.04 g L⁻¹. Using 90 (anhydrous acid) gives 3.60; using the 2:5 ratio upside down gives 2.02.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-practical-salt-analysis-69","question":"In paper chromatography the pencil base line is drawn 2.0 cm above the bottom edge of the paper. When the run is stopped, the solvent front is 12.0 cm and the centre of a spot is 6.5 cm above the bottom edge. The Rf value of the substance is:","options":["0.45","0.65","0.54","0.38"],"answer":0,"explanation":"Distances must be measured from the base line: spot 6.5 − 2.0 = 4.5 cm, solvent 12.0 − 2.0 = 10.0 cm, so Rf = 4.5/10.0 = 0.45. Measuring from the paper edge gives 6.5/12 = 0.54, the commonest slip.","difficulty":"hard","source":"JEE Main"},
  {"id": "chem-practical-salt-analysis-70", "question": "Paper chromatography is classified as partition chromatography because:", "options": ["The cellulose fibres adsorb the components on their surface with different strengths", "Water held in the cellulose acts as the stationary liquid phase, and components distribute between it and the moving solvent", "The components carry different charges and move in an electric field", "Larger molecules are held back in the pores of the paper"], "answer": 1, "explanation": "The paper holds a film of water that is the stationary phase; separation depends on how each component partitions between this water and the mobile solvent. Adsorption on a solid surface is the basis of column (alumina/silica) and TLC chromatography, not paper chromatography.", "difficulty": "hard", "source": "JEE Main"},
  {"id":"chem-practical-salt-analysis-71","question":"For a negatively charged As₂S₃ sol, the correct order of coagulating power of the electrolytes is:","options":["NaCl > BaCl₂ > AlCl₃","Na₃PO₄ > Na₂SO₄ > NaCl","AlCl₃ > BaCl₂ > NaCl","BaCl₂ > AlCl₃ > NaCl"],"answer":2,"explanation":"A negative sol is coagulated by the cations of the added electrolyte, and by the Hardy–Schulze rule the higher the charge the greater the power: Al³⁺ > Ba²⁺ > Na⁺. The anion order PO₄³⁻ > SO₄²⁻ > Cl⁻ applies to a positive sol such as Fe(OH)₃, not to As₂S₃.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-practical-salt-analysis-72","question":"In the preparation of acetanilide from aniline and acetic anhydride (with glacial acetic acid), a pinch of zinc dust is often added. Its role is to:","options":["Act as a Lewis-acid catalyst for acetylation","Convert acetic anhydride into acetyl chloride","Neutralise the acetic acid formed","Prevent oxidation of aniline to coloured products during heating"],"answer":3,"explanation":"Aniline darkens by aerial oxidation, especially on heating; zinc dust (a reducing agent) keeps it from oxidising so the acetanilide is not coloured. Zinc is not a Lewis-acid catalyst here, and it does not make acetyl chloride.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-practical-salt-analysis-73","question":"Potash alum, K₂SO₄·Al₂(SO₄)₃·24H₂O (molar mass 948 g mol⁻¹), is crystallised from a solution containing 3.42 g of Al₂(SO₄)₃ (molar mass 342) and an excess of K₂SO₄. The maximum mass of alum that can be obtained is:","options":["9.48 g","5.16 g","4.74 g","18.96 g"],"answer":0,"explanation":"0.0100 mol Al₂(SO₄)₃ gives 0.0100 mol of K₂SO₄·Al₂(SO₄)₃·24H₂O = 0.0100 × 948 = 9.48 g (equivalently 0.0200 mol of KAl(SO₄)₂·12H₂O × 474). Leaving out the water of crystallisation gives 5.16 g; taking 474 with 0.01 mol gives 4.74 g.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-practical-salt-analysis-74","question":"The enthalpy of neutralisation of HCN by NaOH is −12.1 kJ mol⁻¹, while that of a strong acid by a strong base is −57.1 kJ mol⁻¹. The enthalpy of ionisation of HCN in water is:","options":["−45.0 kJ mol⁻¹","+45.0 kJ mol⁻¹","+69.2 kJ mol⁻¹","+12.1 kJ mol⁻¹"],"answer":1,"explanation":"HCN + OH⁻ → CN⁻ + H₂O can be split into ionisation HCN → H⁺ + CN⁻ (ΔH_ion) and H⁺ + OH⁻ → H₂O (−57.1). So ΔH_ion = −12.1 − (−57.1) = +45.0 kJ mol⁻¹; ionisation absorbs heat, so the sign must be positive.","difficulty":"hard","source":"JEE Main"},
  {"id": "chem-practical-salt-analysis-75", "question": "A salt solution gives a white precipitate with H₂S in ammoniacal medium (group IV). The precipitate dissolves in dilute HCl, and the solution with NaOH gives a white precipitate soluble in excess NaOH. With K₄[Fe(CN)₆] the original solution gives a white (bluish-white) precipitate. The cation is:", "options": ["Al³⁺", "Ni²⁺", "Zn²⁺", "Mg²⁺"], "answer": 2, "explanation": "Only ZnS is a white group IV sulphide, it dissolves in dilute HCl (NiS and CoS do not), Zn(OH)₂ is amphoteric, and Zn₂[Fe(CN)₆] is white. Al³⁺ also forms an amphoteric white hydroxide, but it comes down as Al(OH)₃ in group III, not as a sulphide in group IV.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-practical-salt-analysis-76", "question": "How many of the following statements about the preparation of Mohr's salt and potash alum are correct? (A) Equimolar amounts of the two simple salts are dissolved in the minimum amount of warm water. (B) The solution is boiled for a long time to obtain bigger crystals. (C) Both are double salts, so their aqueous solutions give tests for all the constituent ions. (D) In potash alum the aluminium ion is octahedrally hydrated as [Al(H₂O)₆]³⁺ in the crystal.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, C and D are correct. B is wrong: long heating oxidises Fe²⁺ (the solution turns yellow) and drives off water of crystallisation; the solution is concentrated only to the crystallisation point and then cooled slowly to get large crystals.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-practical-salt-analysis-77", "question": "Assertion (A): The titration of Mohr's salt with KMnO₄ is carried out at room temperature, whereas oxalic acid is titrated with KMnO₄ at about 60–70 °C. Reason (R): Oxalate is oxidised slowly at first until Mn²⁺, formed in the reaction, catalyses it; Fe²⁺ is oxidised rapidly in the cold and would be oxidised by air on heating.", "options": ["Both A and R are true, and R explains A", "Both A and R are true, but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "MnO₄⁻–C₂O₄²⁻ is slow at the start (an induction period that ends once Mn²⁺ autocatalyses it), so the solution is warmed; Fe²⁺ reacts instantly with MnO₄⁻, and warming would only let air oxidise some Fe²⁺. R is the exact reason for A.", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id": "chem-practical-salt-analysis-78", "question": "How many of the following statements about KMnO₄ titrations are correct? (A) HCl is avoided because MnO₄⁻ oxidises Cl⁻ to Cl₂. (B) HNO₃ is avoided because it is itself an oxidising agent and can oxidise the reductant. (C) The end point is the first permanent light pink colour, since KMnO₄ is its own indicator. (D) If too little H₂SO₄ is used, a brown precipitate of MnO₂ appears and the titre becomes unreliable.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are true. Cl⁻ is oxidised (extra titre), HNO₃ oxidises Fe²⁺ or oxalate itself (low titre), MnO₄⁻ is intensely coloured while Mn²⁺ is almost colourless, and in insufficiently acidic solution MnO₄⁻ is reduced only to MnO₂ (3 electrons, brown).", "difficulty": "very-hard", "source": "JEE Main"},
  {"id":"chem-practical-salt-analysis-79","question":"In an iodide–H₂O₂ clock experiment (fixed thiosulphate and starch in every run), the blue colour appears after 80 s when [H₂O₂] = 0.010 M and [I⁻] = 0.010 M, after 40 s when [H₂O₂] = 0.020 M and [I⁻] = 0.010 M, and after 20 s when [H₂O₂] = 0.020 M and [I⁻] = 0.020 M (acid in excess, same temperature). The time for the colour to appear when [H₂O₂] = 0.020 M and [I⁻] = 0.040 M is:","options":["5 s","2.5 s","40 s","10 s"],"answer":3,"explanation":"Rate ∝ 1/t. Doubling [H₂O₂] halves t (first order); doubling [I⁻] at 0.020 M H₂O₂ halves t again (first order), so rate = k[H₂O₂][I⁻]. Going from 0.020 to 0.040 M I⁻ doubles the rate again, so t = 20/2 = 10 s. Reading the times as rates (doubling the time) gives 40 s.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-practical-salt-analysis-80","question":"In a clock run of the H₂O₂–I⁻ reaction the blue colour appears after 50 s. The run is repeated with all concentrations the same except that twice the amount of Na₂S₂O₃ is added (still small compared with H₂O₂ and I⁻). The blue colour now appears after about:","options":["100 s","50 s","25 s","200 s"],"answer":0,"explanation":"The thiosulphate must be used up before blue can appear; twice as much thiosulphate needs twice as much I₂ to be formed, and the initial rate is unchanged, so t ≈ 2 × 50 = 100 s. Thiosulphate is not a reactant in the rate law, so the rate itself does not change.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-practical-salt-analysis-81","question":"100 mL of 0.20 M H₂SO₄ is mixed with 100 mL of 0.20 M NaOH, both at the same initial temperature. Taking ΔH(neutralisation) = −57.1 kJ per mol of water formed, the mass of the solution as 200 g and its specific heat as 4.18 J g⁻¹ K⁻¹ (calorimeter neglected), the expected temperature rise is about:","options":["2.73 K","1.37 K","0.68 K","4.10 K"],"answer":1,"explanation":"H₂SO₄ supplies 0.040 mol H⁺ but NaOH only 0.020 mol OH⁻, so only 0.020 mol water forms: q = 0.020 × 57 100 = 1142 J and ΔT = 1142/(200 × 4.18) = 1.37 K. Taking 0.040 mol of water (counting both H⁺ of the acid) gives 2.73 K, the trap.","difficulty":"very-hard","source":"JEE Main"},
  {"id": "chem-practical-salt-analysis-82", "question": "The enthalpy of solution of anhydrous CuSO₄ is −66.5 kJ mol⁻¹ and that of CuSO₄·5H₂O is +11.7 kJ mol⁻¹. The enthalpy change for CuSO₄(s) + 5H₂O(l) → CuSO₄·5H₂O(s) is:", "options": ["−54.8 kJ mol⁻¹", "+78.2 kJ mol⁻¹", "−78.2 kJ mol⁻¹", "+54.8 kJ mol⁻¹"], "answer": 2, "explanation": "Both salts give the same solution, so by Hess's law ΔH(hydration) = ΔH(soln, anhydrous) − ΔH(soln, hydrate) = −66.5 − 11.7 = −78.2 kJ mol⁻¹. Adding the two values as given (−66.5 + 11.7) gives −54.8, the usual sign slip.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-practical-salt-analysis-83", "question": "Mixtures of o-nitrophenol and p-nitrophenol are separated on a silica-gel TLC plate with a fairly non-polar eluent (hexane–ethyl acetate). Which statement is correct?", "options": ["p-Nitrophenol has the higher Rf, because it is more symmetrical", "Both have the same Rf, because they have the same molar mass and functional groups", "o-Nitrophenol has the higher Rf, because intramolecular hydrogen bonding makes it less polar and less strongly adsorbed on silica", "o-Nitrophenol has the lower Rf, because it hydrogen-bonds more strongly to silica"], "answer": 2, "explanation": "In o-nitrophenol the OH is hydrogen-bonded to the adjacent NO₂, so it binds silica weakly and moves further (higher Rf); in p-nitrophenol the OH is free to hydrogen-bond to the polar silica, so it lags. The same effect makes the ortho isomer steam-volatile.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id":"chem-practical-salt-analysis-84","question":"On a TLC plate, compound X has Rf = 0.65 and compound Y has Rf = 0.40. If the solvent front moves 8.0 cm from the base line, the distance between the centres of the two spots is:","options":["0.25 cm","3.2 cm","5.2 cm","2.0 cm"],"answer":3,"explanation":"X travels 0.65 × 8.0 = 5.2 cm and Y travels 0.40 × 8.0 = 3.2 cm, so they are 5.2 − 3.2 = 2.0 cm apart. 0.25 is the difference of Rf values, not a distance; 5.2 and 3.2 are the individual distances.","difficulty":"very-hard","source":"JEE Main"},
  {"id": "chem-practical-salt-analysis-85", "question": "How many of the following statements about lyophilic and lyophobic sols are correct? (A) Starch and gelatin readily form lyophilic sols just by warming with water. (B) A lyophobic sol, once coagulated, can be re-formed simply by adding the dispersion medium. (C) Lyophilic sols are stabilised both by charge and by a solvation layer. (D) A lyophilic colloid added to a lyophobic sol can protect it against coagulation by electrolytes.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, C and D are correct (D is the basis of the gold number). B is wrong: lyophobic sols are irreversible; once precipitated they cannot be re-formed simply by shaking with the medium, which is a property of lyophilic sols.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id":"chem-practical-salt-analysis-86","question":"A ferric hydroxide sol is prepared by adding a little FeCl₃ to excess NaOH solution (instead of to boiling water) under conditions that give a sol. Compared with the sol made by hydrolysing FeCl₃ in boiling water, this sol is:","options":["Negative, because the particles adsorb the OH⁻ ions present in excess","Also positive, because Fe³⁺ is always the potential-determining ion","Uncharged, because NaOH neutralises all charges","Positive, because Na⁺ is adsorbed on the particles"],"answer":0,"explanation":"A colloid preferentially adsorbs the ion common to it that is present in excess: in boiling water with excess FeCl₃ it adsorbs Fe³⁺ (positive), but in excess NaOH it adsorbs OH⁻, giving [Fe(OH)₃]OH⁻ (negative). The same logic makes AgI positive in excess AgNO₃ and negative in excess KI.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-practical-salt-analysis-87","question":"Which statement about the preparation of p-nitroacetanilide is INCORRECT?","options":["Acetanilide is dissolved in glacial acetic acid and conc. H₂SO₄, and the nitrating mixture is added below about 10 °C","The acetyl group is removed in the same step, so the product is p-nitroaniline","Aniline itself is not nitrated directly, because it is oxidised by HNO₃ and its anilinium ion would direct substitution to the meta position","The mixture is poured onto crushed ice, and the crude product is recrystallised from ethanol, in which the ortho isomer stays dissolved"],"answer":1,"explanation":"Nitration leaves the amide intact; the product is p-nitroacetanilide, and p-nitroaniline needs a separate acid or base hydrolysis. The other three describe the actual method: cold conditions, ice quench, ortho isomer removed in the alcoholic mother liquor, and protection of –NH₂ against oxidation and protonation.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-practical-salt-analysis-88","question":"Aniline yellow is prepared by adding benzenediazonium chloride to aniline in a weakly acidic medium. Which statement is correct?","options":["Aniline yellow is p-hydroxyazobenzene and the coupling needs pH 9–10","Aniline yellow is azobenzene, formed without coupling","Aniline yellow is p-aminoazobenzene; the first product is diazoaminobenzene (N-coupling), which rearranges to the p-isomer in the presence of aniline hydrochloride","Aniline yellow is benzene, formed because H₃PO₂ is present"],"answer":2,"explanation":"Aniline couples with diazonium ion at pH ≈ 4–5 (weakly acidic, so enough free amine but no diazohydroxide). N-coupling gives C₆H₅N=N–NHC₆H₅ first, which rearranges with acid to p-H₂NC₆H₄N=NC₆H₅, aniline yellow. p-Hydroxyazobenzene is the orange dye from phenol, coupled in mildly alkaline solution.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-practical-salt-analysis-89","question":"The minimum mass of iodine needed (with excess NaOH) to convert 2.3 g of ethanol (molar mass 46) completely into iodoform is (I = 127):","options":["38.1 g","19.7 g","25.4 g","50.8 g"],"answer":3,"explanation":"Ethanol is first oxidised by I₂/OH⁻ to ethanal (1 mol I₂), which is then tri-iodinated (3 mol I₂) and cleaved: C₂H₅OH + 4I₂ + 6NaOH → CHI₃ + HCOONa + 5NaI + 5H₂O. So 0.05 mol ethanol needs 0.20 mol I₂ = 0.20 × 254 = 50.8 g. Counting only the 3 mol for iodination (as for acetone) gives 38.1 g; 19.7 g is the mass of iodoform formed.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-practical-salt-analysis-90","question":"How many of the following compounds give iodoform when warmed with I₂ and NaOH: ethanol, methanol, propan-2-ol, propan-1-ol, acetophenone, ethanoic acid, butan-2-one, pentan-3-one?","options":["4","3","5","6"],"answer":0,"explanation":"Ethanol, propan-2-ol (both CH₃CH(OH)–, oxidised to CH₃CO–), acetophenone and butan-2-one (CH₃CO–) give iodoform: 4. Methanol and propan-1-ol lack the CH₃–C(O/OH) unit; in ethanoic acid the CH₃CO– is part of a carboxylate whose α-hydrogens are not acidic enough; pentan-3-one has only ethyl groups.","difficulty":"very-hard","source":"JEE Main"},
  {"id": "chem-practical-salt-analysis-91", "question": "A white precipitate obtained in group I dissolves partly in hot water. The undissolved residue turns black with NH₄OH, and the hot-water extract gives a yellow precipitate with K₂CrO₄. The cations present are:", "options": ["Ag⁺ and Pb²⁺", "Hg₂²⁺ and Pb²⁺", "Ag⁺ and Hg₂²⁺", "Pb²⁺ only"], "answer": 1, "explanation": "PbCl₂ dissolves in hot water (yellow PbCrO₄ with chromate). Hg₂Cl₂ is blackened by NH₄OH (Hg + Hg(NH₂)Cl), whereas AgCl would dissolve in NH₄OH as [Ag(NH₃)₂]⁺ and not turn black. So the residue is Hg₂Cl₂, not AgCl.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-practical-salt-analysis-92", "question": "Ni²⁺ is not precipitated by H₂S in dilute HCl (group II), yet the black NiS precipitated in group IV does not dissolve in dilute HCl. The best explanation is:", "options": ["NiS has a larger Ksp than CuS, so it never forms in acid", "NiS is precipitated in group IV only because Ni²⁺ is oxidised to Ni³⁺ by air", "The freshly formed NiS ages quickly to a less soluble form; its precipitation from acid is kinetically slow, but once formed it is too insoluble to redissolve in dilute HCl", "Dilute HCl oxidises NiS to NiSO₄, which is insoluble"], "answer": 2, "explanation": "Nickel (and cobalt) sulphides precipitate slowly from acidic solution, so they miss group II, but the precipitate converts to a more insoluble form and then needs aqua regia to dissolve. That is why NiS/CoS are separated from ZnS/MnS by treating the group IV precipitate with cold dilute HCl.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id":"chem-practical-salt-analysis-93","question":"Match the cation (Column I) with its confirmatory test (Column II). (a) Ni²⁺, (b) Ba²⁺, (c) Ca²⁺, (d) Fe³⁺. (1) Yellow precipitate with K₂CrO₄ in acetic acid medium, (2) Red precipitate with dimethylglyoxime in ammoniacal medium, (3) Prussian blue with potassium ferrocyanide, (4) White precipitate with ammonium oxalate, insoluble in acetic acid.","options":["a-2, b-4, c-1, d-3","a-2, b-1, c-3, d-4","a-3, b-1, c-4, d-2","a-2, b-1, c-4, d-3"],"answer":3,"explanation":"Ni²⁺ gives red Ni(dmg)₂; BaCrO₄ precipitates even in acetic acid, while SrCrO₄/CaCrO₄ do not; Ca²⁺ gives white CaC₂O₄; Fe³⁺ gives Fe₄[Fe(CN)₆]₃ (Prussian blue). The chromate test in acetic acid is the standard way to separate Ba²⁺ from Ca²⁺ and Sr²⁺.","difficulty":"very-hard","source":"JEE Main"},
  {"id": "chem-practical-salt-analysis-94", "question": "The group III precipitate of a mixture is boiled with NaOH and H₂O₂. A brown residue remains, and the filtrate, on acidification with dilute HCl followed by addition of NH₄OH, gives a white gelatinous precipitate. The cations present are:", "options": ["Fe³⁺ and Al³⁺", "Fe³⁺ and Zn²⁺", "Al³⁺ and Cr³⁺", "Fe³⁺ only"], "answer": 0, "explanation": "Fe(OH)₃ is not amphoteric and stays as a brown residue; Al(OH)₃ dissolves as aluminate and is re-precipitated as white gelatinous Al(OH)₃ by NH₄Cl/NH₄OH. Cr³⁺ would give yellow chromate in the filtrate, and Zn²⁺ is not in group III at all.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id":"chem-practical-salt-analysis-95","question":"A salt solution gives a pale yellow precipitate with AgNO₃ that dissolves only partly in dilute NH₃ but completely in concentrated NH₃. When the dry salt is heated with K₂Cr₂O₇ and conc. H₂SO₄, reddish-brown vapours evolve; these vapours passed into NaOH give a colourless solution that gives no yellow precipitate with lead acetate. The anion is:","options":["Cl⁻","Br⁻","NO₃⁻","I⁻"],"answer":1,"explanation":"AgBr is pale yellow and dissolves only in concentrated NH₃. With dichromate and acid, bromide gives Br₂ vapour (reddish brown), not CrO₂Cl₂, so the NaOH solution contains no chromate and gives no yellow PbCrO₄. A chloride would give a yellow solution and yellow PbCrO₄; that difference is the whole point of the chromyl chloride test.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-practical-salt-analysis-96","question":"How many of the following give a positive chromyl chloride test (orange-red vapours that give a yellow solution in NaOH, which gives a yellow precipitate with lead acetate)? NaCl, HgCl₂, KBr, NH₄Cl, AgCl, KCl.","options":["2","4","3","5"],"answer":2,"explanation":"NaCl, NH₄Cl and KCl (ionic chlorides) give CrO₂Cl₂: 3. HgCl₂ is covalent and AgCl is insoluble and very stable, so they do not give the test reliably (likewise PbCl₂, SnCl₄); KBr gives Br₂, which dissolves in NaOH without forming chromate.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-practical-salt-analysis-97","question":"A salt containing both NO₂⁻ and NO₃⁻ is to be tested for nitrate by the brown ring test. Which step is essential before the test?","options":["Make the solution strongly alkaline with NaOH","Add AgNO₃ to remove the nitrite as AgNO₂","Add conc. HCl to convert the nitrate into nitrite","Boil the solution with sulphamic acid (or urea and dilute acid) to destroy the nitrite"],"answer":3,"explanation":"NO₂⁻ itself gives a brown ring (even with dilute acid), so a positive test would not prove nitrate. Sulphamic acid converts NO₂⁻ to N₂ (HNO₂ + NH₂SO₃H → N₂ + H₂SO₄ + H₂O) and leaves NO₃⁻ untouched. Bromide and iodide also interfere and are removed with Ag₂SO₄ for the same reason.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-practical-salt-analysis-98","question":"A colourless salt gives effervescence with dilute H₂SO₄; the gas turns lime water milky and has no effect on acidified K₂Cr₂O₇ paper. The salt's solution gives a white precipitate with ammonium oxalate and a brick-red flame. The salt is:","options":["CaCO₃","BaCO₃","SrCO₃","CaSO₃"],"answer":0,"explanation":"CO₂ turns lime water milky but does not turn dichromate green (SO₂ from a sulphite would), so the anion is carbonate, not sulphite. A brick-red flame and white CaC₂O₄ with ammonium oxalate mean Ca²⁺ (barium gives an apple-green flame and strontium a crimson one, and SrC₂O₄/BaC₂O₄ would not be the confirmatory test).","difficulty":"very-hard","source":"JEE Main"},
  {"id": "chem-practical-salt-analysis-99", "question": "A blue crystalline salt gives a deep blue solution with excess aqueous NH₃ and a chocolate-brown precipitate with K₄[Fe(CN)₆]. Its solution gives a precipitate with BaCl₂ that is insoluble in conc. HCl. When the solution is acidified with dilute HCl and H₂S is passed, a black precipitate forms that dissolves in hot 50% HNO₃. The salt is:", "options": ["NiSO₄", "CuSO₄", "CuCl₂", "FeSO₄"], "answer": 1, "explanation": "Deep blue [Cu(NH₃)₄]²⁺, brown Cu₂[Fe(CN)₆], and black CuS (group II, soluble in hot dilute HNO₃) identify Cu²⁺; the BaSO₄ precipitate identifies sulphate. Ni²⁺ gives a blue-violet ammine but no group II precipitate; CuCl₂ would give no BaCl₂ precipitate.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id":"chem-practical-salt-analysis-100","question":"A white salt is heated with NaOH; no ammonia is evolved. Its solution gives no precipitate in groups I–IV but gives a white precipitate with (NH₄)₂CO₃ in the presence of NH₄Cl and NH₄OH. The precipitate dissolves in acetic acid, and this solution gives a yellow precipitate with K₂CrO₄. The salt also gives a white precipitate with dilute H₂SO₄ and, with conc. H₂SO₄ and MnO₂, a greenish-yellow gas. The salt is:","options":["CaCl₂","SrCl₂","BaCl₂","Ba(NO₃)₂"],"answer":2,"explanation":"Group V carbonate soluble in acetic acid and re-precipitated as yellow BaCrO₄ points to Ba²⁺ (Ca²⁺/Sr²⁺ do not give a chromate precipitate in acetic acid), confirmed by insoluble BaSO₄ with dilute H₂SO₄. MnO₂ + conc. H₂SO₄ liberating Cl₂ identifies chloride; a nitrate would give brown NO₂ fumes instead.","difficulty":"very-hard","source":"JEE Main"},
];

export default questions;
